head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.pSndNo;
scwin.pMktCd;
scwin.pSndlocCd;
scwin.vScrenID = 'ULDSTF35006_POP.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Search = function(sndno, mktcd, sndcd) {
    var url = "/AtsContactInfo.do?method=listEmContactNotiDtl" + "&SND_NO=" + sndno + "&LD_MKT_TP_CD=" + mktcd + "&SNDLOC_TP_CD=" + sndcd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 그리드의 데이타 조회
    dts_list.DataID = encodeURI(url);
    dts_list.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.dts_list_OnLoadCompleted = function(rowcount) {
    if (dts_list.errorMsg) {
        $c.win.alert("조회할 수 없습니다. 시스템 관리자에게 문의하세요");
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_list_OnLoadError = function() {
    $c.win.alert("조회할 수 없습니다. 시스템 관리자에게 문의하세요");
    $c.cm.CloseWin('', grd_Grid);
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    scwin.pSndNo = $c.frame.path("../").scwin.pSndNo;
    scwin.pMktCd = $c.frame.path("../").scwin.pMktCd;
    scwin.pSndlocCd = $c.frame.path("../").scwin.pSndlocCd;
    scwin.fn_Search(scwin.pSndNo, scwin.pMktCd, scwin.pSndlocCd);
};
